function cookieValue(name){return document.cookie.split('; ').find(x=>x.startsWith(name+'='))?.split('=').slice(1).join('=')||''}
async function api(path,method='GET',body){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),path.includes('speaking/')||path.includes('writing/submit')||path.includes('pronunciation/ai')?70000:20000);
 const unsafe=!['GET','HEAD','OPTIONS'].includes(method.toUpperCase()),csrf=decodeURIComponent(cookieValue('ss_csrf'));
 try{const r=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(unsafe&&csrf?{'X-CSRF-Token':csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:controller.signal});const data=await r.json().catch(()=>({}));if(!r.ok){const error=Error(data.detail||'Có lỗi xảy ra');error.status=r.status;throw error}return data}
 catch(error){if(error.name==='AbortError')throw Error('Yêu cầu quá thời gian. Vui lòng thử lại.');throw error}finally{clearTimeout(timeout)}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function count(){return Object.values(state.progress).filter(p=>p.level>0).length}
