function vocabularyStage(){return state.stage==='A0'?'A1':state.stage}
async function loadVocabulary(reset=true){if(state.reviewMode)return;if(state.vocabLoading)return;state.vocabLoading=true;try{const page=reset?1:state.vocabPage+1,params=new URLSearchParams({level:vocabularyStage(),page:String(page),page_size:'80'});if(state.topic!=='all')params.set('topic',state.topic);if(state.vocabSearch.trim())params.set('q',state.vocabSearch.trim());const result=await api('vocabulary/library?'+params);state.words=reset?result.items:[...state.words,...result.items.filter(item=>!state.words.some(word=>word.id===item.id))];state.vocabPage=result.page;state.vocabTotal=result.total;state.vocabHasMore=result.has_more}finally{state.vocabLoading=false}}
function filtered(){const source=state.reviewMode?state.dueWords:state.words;const query=state.vocabSearch.trim().toLocaleLowerCase('vi');return source.filter(w=>(w.stage||'A1')===vocabularyStage()).filter(w=>state.topic==='all'||(w.topic_slugs||[]).includes(state.topic)).filter(w=>!query||`${w.word} ${w.meaning}`.toLocaleLowerCase('vi').includes(query)).filter(w=>{const level=state.progress[w.id]?.level||0;return state.vocabStatus==='all'||(state.vocabStatus==='new'&&level===0)||(state.vocabStatus==='learning'&&level>0&&level<3)||(state.vocabStatus==='mastered'&&level>=3)})}
