let speechVoices=[],lastSpeech=null;
const speechSettings={voiceURI:localStorage.getItem('ss_speech_voice')||'',speed:Math.max(.75,Math.min(1.25,Number(localStorage.getItem('ss_speech_speed'))||1))};
function refreshSpeechVoices(){if(!speechSupported)return;speechVoices=speechSynthesis.getVoices().filter(v=>/^en(?:-|_)/i.test(v.lang)).sort((a,b)=>{const rank=v=>(/en-US/i.test(v.lang)?0:/en-GB/i.test(v.lang)?1:2)+(/natural|enhanced|premium|google|microsoft/i.test(v.name)?0:10);return rank(a)-rank(b)||a.name.localeCompare(b.name)});document.querySelectorAll('[data-speech-voice]').forEach(select=>{const current=speechSettings.voiceURI;select.innerHTML=speechVoices.length?speechVoices.map(v=>`<option value="${esc(v.voiceURI)}" ${v.voiceURI===current?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join(''):'<option value="">Chưa tải được giọng tiếng Anh</option>';select.disabled=!speechVoices.length;if(!current&&speechVoices[0]){speechSettings.voiceURI=speechVoices[0].voiceURI;select.value=speechSettings.voiceURI}})}
function speechControls(){return `<div class="speech-settings" aria-label="Cài đặt giọng đọc trình duyệt"><label>Giọng tiếng Anh <select data-speech-voice><option value="">Đang tải danh sách giọng…</option></select></label><label>Tốc độ <input data-speech-speed type="range" min="0.75" max="1.25" step="0.05" value="${speechSettings.speed}"><output data-speech-rate>${speechSettings.speed.toFixed(2)}x</output></label><button class="secondary" data-speech-stop>■ Dừng</button><button class="secondary" data-speech-replay ${lastSpeech?'':'disabled'}>↻ Phát lại</button><small data-speech-status>${speechSupported?'Giọng đọc chạy trên thiết bị, không dùng Gemini.':'Trình duyệt này không hỗ trợ Web Speech API.'}</small></div>`}
function stopSpeech(){if(speechSupported)speechSynthesis.cancel()}
function say(text,rate=speechSettings.speed){const clean=String(text||'').trim();if(!clean)return false;if(!speechSupported){toast('Trình duyệt không hỗ trợ Web Speech API. Không có yêu cầu Gemini nào được gửi.');return false}stopSpeech();const bounded=Math.max(.75,Math.min(1.25,Number(rate)||speechSettings.speed)),utterance=new SpeechSynthesisUtterance(clean),voice=speechVoices.find(v=>v.voiceURI===speechSettings.voiceURI)||speechVoices[0]||null;utterance.lang=voice?.lang||'en-US';utterance.voice=voice;utterance.rate=bounded;utterance.onerror=event=>{if(event.error!=='canceled'&&event.error!=='interrupted')toast('Không thể phát giọng trình duyệt: '+event.error)};lastSpeech={text:clean,rate:bounded};speechSynthesis.speak(utterance);document.querySelectorAll('[data-speech-replay]').forEach(button=>button.disabled=false);if(!speechVoices.length)toast('Danh sách giọng chưa tải; đang dùng giọng tiếng Anh mặc định của thiết bị.');return true}
function bindSpeechControls(root=document){root.querySelectorAll('[data-speech-voice]').forEach(select=>select.onchange=()=>{speechSettings.voiceURI=select.value;localStorage.setItem('ss_speech_voice',select.value)});root.querySelectorAll('[data-speech-speed]').forEach(input=>input.oninput=()=>{speechSettings.speed=Math.max(.75,Math.min(1.25,+input.value));localStorage.setItem('ss_speech_speed',speechSettings.speed);root.querySelectorAll('[data-speech-rate]').forEach(output=>output.textContent=speechSettings.speed.toFixed(2)+'x')});root.querySelectorAll('[data-speech-stop]').forEach(button=>button.onclick=stopSpeech);root.querySelectorAll('[data-speech-replay]').forEach(button=>button.onclick=()=>lastSpeech&&say(lastSpeech.text,lastSpeech.rate));refreshSpeechVoices()}
function currentSpeechText(){if(state.view==='learn'||state.view==='speak')return currentWord()?.word||'';if(state.view==='quiz')return state.quiz?.word?.word||'';if(state.view==='reverse'&&state.reverseFeedback){const pool=filtered();return pool[state.reverseIndex%Math.max(1,pool.length)]?.word||''}if(state.view==='dictation')return exerciseList()[state.exerciseIndex%Math.max(1,exerciseList().length)]?.sentence||'';if(state.view==='grammar'&&state.grammarSession){const ex=state.grammarSession.exercises[state.grammarExerciseIndex%state.grammarSession.exercises.length];return [ex?.prompt,...(state.grammarLesson?.examples||[]).map(x=>x.english)].filter(Boolean).join('. ')}if(state.view==='skills'&&state.skillLesson){if(state.skillLesson.skill==='listening')return state.skillLesson.transcript_en||'';if(state.view==='skills'&&(state.skillLesson.skill==='reading'||state.skillLesson.skill==='speaking'))return state.skillLesson.content_en||''}return''}
