async function openGrammarLesson(id){try{state.grammarLesson=await api('grammar/lessons/'+id);state.grammarSession={title:state.grammarLesson.title,exercises:state.grammarLesson.exercises,isTest:false};state.grammarExerciseIndex=0;state.grammarFeedback=null;renderGrammarLesson()}catch(e){toast(e.message)}}
async function openGrammarUnitTest(id){try{const data=await api('grammar/units/'+id+'/test');state.grammarLesson=null;state.grammarSession={title:'Bài kiểm tra · '+data.unit.title,exercises:data.exercises,isTest:true,unit:data.unit};state.grammarExerciseIndex=0;state.grammarFeedback=null;renderGrammarLesson()}catch(e){toast(e.message)}}
function renderGrammarLesson(){
 const session=state.grammarSession;if(!session||!session.exercises.length){grammar();return}const lesson=state.grammarLesson,ex=session.exercises[state.grammarExerciseIndex%session.exercises.length],fb=state.grammarFeedback;
 const intro=lesson?`<div class="lesson-theory"><div><div class="eyebrow">${esc(lesson.level)} · ${esc(lesson.topic)}</div><h1>${esc(lesson.title)}</h1><p>${esc(lesson.explanation_vi)}</p><div class="formula"><b>Công thức</b><code>${esc(lesson.formula)}</code></div></div><div class="examples"><h3>Ví dụ Anh–Việt</h3>${lesson.examples.map(x=>`<p><b>${esc(x.english)}</b><br><span>${esc(x.vietnamese)}</span></p>`).join('')}</div></div><details class="common-errors"><summary>Lỗi thường gặp</summary>${lesson.common_errors.map(x=>`<div><del>${esc(x.wrong)}</del><br><b>✓ ${esc(x.correct)}</b></div>`).join('')}</details>`:`<div class="lesson-theory"><div><div class="eyebrow">${esc(session.unit.level)} · KIỂM TRA CUỐI UNIT</div><h1>${esc(session.title)}</h1><p>Trả lời đúng ít nhất 8/10 câu để hoàn thành unit.</p></div></div>`;
 const vocab=(ex.vocabulary||[]).slice(0,6).map(w=>`<span class="vocab-chip" title="${esc(w.ipa)}">${esc(w.word)} · ${esc(w.meaning)}</span>`).join('');
 const answerUi=ex.kind==='multiple_choice'?`<div class="grammar-options">${ex.options.map(o=>`<button class="choice" data-grammar-answer="${esc(o)}" ${fb?'disabled':''}>${esc(o)}</button>`).join('')}</div>`:`<form id="grammarAnswerForm"><input class="answer-input" id="grammarAnswer" autocomplete="off" spellcheck="false" placeholder="Nhập câu trả lời…" ${fb?'disabled':''} required><button class="primary" ${fb?'disabled':''}>Kiểm tra →</button></form>`;
 $('#content').innerHTML=`<button class="textbtn" id="backGrammar">← Quay lại lộ trình</button>${intro}<div class="grammar-exercise"><div class="exercise-meta"><span>${esc(grammarKindNames[ex.kind])}</span><b>Câu ${state.grammarExerciseIndex%session.exercises.length+1}/${session.exercises.length}</b></div><h2>${esc(ex.prompt)}</h2>${vocab?`<div class="vocab-hints"><small>Từ vựng liên quan</small>${vocab}</div>`:''}${answerUi}${fb?`<div class="feedback ${fb.correct?'ok':'no'}"><h3>${fb.correct?'🎉 Chính xác!':'💡 Chưa chính xác'}</h3><p>Đáp án: <b>${esc(fb.expected)}</b></p><p>${esc(fb.explanation_vi)}</p><button class="primary" id="nextGrammar">${state.grammarExerciseIndex+1>=session.exercises.length?'Xem kết quả →':'Câu tiếp theo →'}</button></div>`:''}</div><p class="hint">${state.user?'Kết quả được lưu riêng trong tài khoản.':'Đăng nhập để làm bài và lưu tiến độ.'}</p>`;
 $('#backGrammar').onclick=()=>{state.grammarLesson=null;state.grammarSession=null;state.grammarFeedback=null;grammar()};
 document.querySelectorAll('[data-grammar-answer]').forEach(b=>b.onclick=()=>submitGrammarAnswer(ex,b.dataset.grammarAnswer));
 if($('#grammarAnswerForm'))$('#grammarAnswerForm').onsubmit=e=>{e.preventDefault();submitGrammarAnswer(ex,$('#grammarAnswer').value)};
 if($('#nextGrammar'))$('#nextGrammar').onclick=async()=>{if(state.grammarExerciseIndex+1>=session.exercises.length){if(state.user)state.grammarProgress=await api('grammar/progress');state.grammarLesson=null;state.grammarSession=null;state.grammarFeedback=null;grammar()}else{state.grammarExerciseIndex++;state.grammarFeedback=null;renderGrammarLesson()}};
}
async function submitGrammarAnswer(ex,answer){if(!state.user){openAuth();return}try{state.grammarFeedback=await api('grammar/check','POST',{exercise_id:ex.id,answer});renderGrammarLesson()}catch(e){toast(e.message)}}
