function exerciseView(mode){const pool=exerciseList();if(!pool.length)return;const ex=pool[state.exerciseIndex%pool.length],fb=state.exerciseFeedback;const titles={grammar:['Ngữ pháp 📖','Điền từ còn thiếu và hiểu quy tắc ngữ pháp.'],rewrite:['Viết lại câu ✍️','Dịch câu tiếng Việt thành một câu tiếng Anh hoàn chỉnh.'],dictation:['Nghe và viết lại câu 🎧','Nghe câu tiếng Anh rồi gõ chính xác nội dung bạn nghe được.']};const [title,desc]=titles[mode];const imported=libraryExerciseCache[mode]||[];$('#content').innerHTML=head(title,desc)+(imported.length?`<div class="panel"><h3>📚 Bài tập từ thư viện mở (${imported.length})</h3><p>Chọn bài bên dưới để luyện tập và lưu tiến độ.</p><select id="libExerciseSelect">${imported.map((e,i)=>`<option value="${i}">${esc(e.prompt.slice(0,75))}</option>`).join('')}</select><p id="libExercisePrompt" style="margin-top:12px">${esc(imported[0].prompt)}</p><input id="libExerciseAnswer" class="answer-input" placeholder="Nhập đáp án"><button class="primary" id="libExerciseCheck">Kiểm tra bài từ thư viện →</button><div id="libExerciseFeedback"></div></div>`:`<button class="secondary" id="loadLibrary">📚 Tải bài tập thư viện mở</button>`)+`<div class="game"><div class="eyebrow">${esc(state.stage)} · ${esc(ex.topic)} · BÀI ${state.exerciseIndex%pool.length+1}/${pool.length}</div>${mode==='grammar'?`<h2 class="exercise-question">${esc(ex.blank)}</h2><p class="muted">Điền phần còn thiếu vào ô trống.</p>`:mode==='rewrite'?`<h2 class="exercise-question">${esc(ex.vi)}</h2><p class="muted">Viết thành câu tiếng Anh:</p>`:`<h2 class="exercise-question">🎧 Nghe thật kỹ</h2><button class="secondary" id="playAudio">🔊 Phát câu tiếng Anh</button> <button class="secondary" id="slowAudio">🐢 Nghe chậm</button><p class="muted">Có thể nghe lại nhiều lần trước khi trả lời.</p>`}<form id="exerciseForm"><input id="exerciseInput" class="answer-input" autocomplete="off" spellcheck="false" placeholder="Nhập câu trả lời..." required ${fb?'disabled':''}><button class="primary" ${fb?'disabled':''}>Kiểm tra đáp án →</button></form>${fb?`<div class="feedback">${fb.correct?'🎉 Chính xác!':'💡 Cần luyện thêm.'}<p>Đáp án mẫu: <b>${esc(fb.expected)}</b></p><p>${esc(fb.explanation)}</p><button class="secondary" id="playAnswer">🔊 Nghe đáp án</button> <button class="primary" id="exerciseNext">Bài tiếp theo →</button></div>`:''}</div><p class="hint">${state.user?'Kết quả được lưu trong tài khoản của bạn.':'Đăng nhập để lưu kết quả bài tập.'} · Chế độ viết câu chấm theo đáp án mẫu, chưa đánh giá các cách diễn đạt tương đương.</p>`;if($('#loadLibrary'))$('#loadLibrary').onclick=()=>loadLibraryExercises(mode);if($('#libExerciseSelect')){const select=$('#libExerciseSelect');select.onchange=()=>{$('#libExercisePrompt').textContent=imported[+select.value].prompt;$('#libExerciseFeedback').textContent=''};$('#libExerciseCheck').onclick=async()=>{if(!state.user){openAuth();return}try{const e=imported[+select.value];const r=await api('library/check','POST',{exercise_id:e.id,answer:$('#libExerciseAnswer').value});$('#libExerciseFeedback').textContent=(r.correct?'🎉 Đúng!':'💡 Chưa đúng. Đáp án: '+r.expected)+' '+r.explanation}catch(err){toast(err.message)}}};$('#exerciseForm').onsubmit=async e=>{e.preventDefault();const answer=$('#exerciseInput').value;if(!state.user){openAuth();return}if(state.user){try{state.exerciseFeedback=await api('check-exercise','POST',{exercise_id:ex.id,mode,answer});state.exerciseProgress=await api('exercise-progress')}catch(e){toast(e.message);return}}else{const expected=mode==='grammar'?ex.blank.match(/___/)?'':ex.sentence:ex.sentence;state.exerciseFeedback={correct:mode==='grammar'?false:norm(answer)===norm(expected),expected:mode==='grammar'?'Đăng nhập để kiểm tra bài ngữ pháp':expected,explanation:'Đăng nhập để kiểm tra đáp án ngữ pháp và lưu kết quả.'}}exerciseView(mode)};if($('#playAudio'))$('#playAudio').onclick=()=>say(ex.sentence);if($('#slowAudio'))$('#slowAudio').onclick=()=>say(ex.sentence,0.65);if($('#playAnswer'))$('#playAnswer').onclick=()=>say(ex.sentence);if($('#exerciseNext'))$('#exerciseNext').onclick=()=>{state.exerciseIndex++;state.exerciseFeedback=null;exerciseView(mode)}}

function openAuth(){state.mode='login';authMode();$('#modal').classList.remove('hidden')}
function authMode(){const reg=state.mode==='register';$('#authTitle').textContent=reg?'Tạo tài khoản miễn phí':'Chào mừng trở lại!';$('#nameField').classList.toggle('hidden',!reg);$('#password').autocomplete=reg?'new-password':'current-password';$('#authSubmit').textContent=reg?'Đăng ký':'Đăng nhập';$('#switchAuth').textContent=reg?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký';$('#authError').textContent=''}
async function refreshPersonalization(){if(!state.user)return;const [dashboard,path,latest]=await Promise.all([api('dashboard'),api('learning-path'),api('placement/latest')]);state.dashboard=dashboard;state.learningPath=path;state.placementLatest=latest.attempt;state.stage=dashboard.profile.current_level}
async function sync(){try{state.user=await api('me');const [rows,due,exercise,grammarProgress,topicProgress]=await Promise.all([api('progress'),api('review-queue?limit=100'),api('exercise-progress'),api('grammar/progress'),api('vocabulary/topic-progress')]);state.progress=Object.fromEntries(rows.map(p=>[p.word_id,p]));state.dueWords=due;state.exerciseProgress=exercise;state.grammarProgress=grammarProgress;state.topicProgress=Object.fromEntries(topicProgress.map(p=>[p.slug,p]));await refreshPersonalization()}catch(error){if(error.status!==401)console.warn('Không thể đồng bộ:',error.message);state.user=null;state.dashboard=null;state.learningPath=null;state.topicProgress={};state.grammarProgress={lessons:[],units:[],summary:{}}}}
document.querySelectorAll('.nav button').forEach(b=>{b.setAttribute('aria-label',b.querySelector('span')?.textContent||b.dataset.view);b.onclick=()=>nav(b.dataset.view)});$('#authBtn').onclick=async()=>{if(state.user){await api('logout','POST').catch(()=>{});state.user=null;state.mode='login';state.progress={};state.dashboard=null;state.learningPath=null;state.placementLatest=null;state.grammarProgress={lessons:[],units:[],summary:{}};toast('Đã đăng xuất');render()}else openAuth()};$('#closeModal').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.add('hidden')};$('#switchAuth').onclick=()=>{state.mode=state.mode==='login'?'register':'login';authMode()};$('#authForm').onsubmit=async e=>{e.preventDefault();const submit=$('#authSubmit');submit.disabled=true;const payload={email:$('#email').value,password:$('#password').value,...(state.mode==='register'?{name:$('#name').value}:{})};try{const r=await api(state.mode==='register'?'register':'login','POST',payload);state.user=r.user;$('#modal').classList.add('hidden');await sync();render();toast('Xin chào, '+state.user.name+'!')}catch(err){$('#authError').textContent=err.message}finally{submit.disabled=false}};
async function bootstrap(){try{const [lessons,curriculum,skillCatalog,runtime,topicCatalog]=await Promise.all([api('lessons'),api('grammar/curriculum'),api('skills/catalog'),api('runtime-config'),api('vocabulary/topics')]);state.levels=lessons.levels;state.lessons=lessons.exercises;state.grammarCurriculum=curriculum;state.skillCatalog=skillCatalog;state.runtime=runtime;state.topicCatalog=topicCatalog;await sync();await loadVocabulary(true);render()}catch(error){$('#content').innerHTML=`<div class="panel"><h1>Không tải được dữ liệu</h1><p>${esc(error.message)}</p><button class="primary" id="retryBootstrap">Thử lại</button></div>`;$('#retryBootstrap').onclick=bootstrap}}
bootstrap();

// Gemini speaking: two modes, turn-based via browser speech recognition + Gemini text,
// and real-time PCM streaming via an authenticated FastAPI WebSocket proxy.
let speakingHistory=[], liveSocket=null, micStream=null, micContext=null, micProcessor=null, audioContext=null, playAt=0;
let speakingMode='turn',speakingLevel='A1',speakingTopic='Daily life';
function conversation(){
 $('#content').innerHTML=head('🎙 AI Speaking Partner','Luyện hội thoại tiếng Anh với Gemini: từng lượt hoặc trực tiếp như gọi điện.')+`
 ${state.speakingSession?`<div class="speaking-task"><div class="eyebrow">NHIỆM VỤ ${esc(state.speakingSession.lesson.level)}</div><h2>${esc(state.speakingSession.lesson.title)}</h2><p>${esc(state.speakingSession.lesson.content_en)}</p></div>`:''}
 <div class="speakpanel"><div class="speakcontrols"><label>Chế độ <select id="speakingMode" ${state.speakingSession?'disabled':''}><option value="turn">🎤 Nói từng lượt</option><option value="live" ${state.runtime.gemini_live_enabled?'':'disabled'}>📞 ${state.runtime.gemini_live_enabled?'Hội thoại trực tiếp':'Live đang tắt'}</option></select></label>
 <label>Trình độ <select id="speakingLevel">${['A0','A1','A2','B1'].map(x=>`<option>${x}</option>`).join('')}</select></label>
 <label>Chủ đề <select id="speakingTopic">${['Daily life','At a restaurant','Travel','Job interview','Shopping','School'].map(x=>`<option>${x}</option>`).join('')}</select></label></div>
 <p class="hint">Chế độ từng lượt dùng nhận dạng giọng nói của trình duyệt và giọng đọc hệ thống. Chế độ trực tiếp truyền âm thanh tới Gemini Live qua backend, không đưa API key ra trình duyệt.</p>
 <div class="live-quota-warning" role="note"><b>⚠ Gemini Live sử dụng quota API.</b> ${state.runtime.gemini_live_enabled?'Chỉ kết nối sau khi bạn chọn Live, xác nhận và nhấn bắt đầu. Hệ thống không tự kết nối lại.':'Tính năng đang tắt trên môi trường thử nghiệm; các bài học thông thường vẫn hoạt động.'}</div>
 <div class="speaklog" id="speakLog" aria-live="polite"><div class="bubble">Hi! 👋 Choose a topic and say hello. I'll help you practice English!</div></div>
 <div class="speakactions"><button class="primary" id="startSpeaking">🎤 Bắt đầu nói</button><button class="outline" id="stopSpeaking">■ Dừng</button>${state.speakingSession?'<button class="secondary" id="evaluateSpeaking">Đánh giá nhiệm vụ</button>':''}</div>
 <form class="chat-form" id="speakingForm"><input id="speakingText" maxlength="1200" placeholder="Hoặc nhập câu tiếng Anh..." required><button class="primary">Gửi →</button></form>
 <div class="feedback" id="speakStatus">Sẵn sàng. Hãy đăng nhập trước khi luyện nói.</div></div>`;
 $('#speakingMode').value=speakingMode;$('#speakingLevel').value=speakingLevel;$('#speakingTopic').value=speakingTopic;
 $('#speakingMode').onchange=e=>{stopLive();speakingMode=e.target.value};
 $('#speakingLevel').onchange=e=>speakingLevel=e.target.value;
 $('#speakingTopic').onchange=e=>speakingTopic=e.target.value;
 $('#startSpeaking').onclick=()=>speakingMode==='live'?startLive():listenTurn();
 $('#stopSpeaking').onclick=()=>{stopLive();$('#speakStatus').textContent='Đã dừng'};
 if($('#evaluateSpeaking'))$('#evaluateSpeaking').onclick=evaluateSpeakingTask;
 $('#speakingForm').onsubmit=async e=>{e.preventDefault();const el=$('#speakingText'),v=el.value.trim();if(!v)return;el.value='';if(speakingMode==='live'&&liveSocket?.readyState===1){logSpeaking(v,true);liveSocket.send(JSON.stringify({type:'text',text:v}))}else await submitTurn(v)};
}
function logSpeaking(text,mine){const log=$('#speakLog');if(!log)return;const div=document.createElement('div');div.className='bubble'+(mine?' mine':'');div.textContent=(mine?'Bạn: ':'AI: ')+text;log.append(div);log.scrollTop=log.scrollHeight}
async function submitTurn(message){if(!state.user){openAuth();return}logSpeaking(message,true);$('#speakStatus').textContent='Gemini đang trả lời...';try{const res=await api('speaking/turn','POST',{message,level:speakingLevel,topic:speakingTopic,history:speakingHistory.slice(-10),session_id:state.speakingSession?.id||null});speakingHistory.push({role:'user',text:message},{role:'model',text:res.reply});speakingHistory=speakingHistory.slice(-12);logSpeaking(res.reply,false);say(res.reply.split(/(?:Gợi ý|Sửa lỗi|Correction|Lưu ý):/i)[0]);$('#speakStatus').textContent='Đã trả lời. Tiếp tục luyện nói nhé!'}catch(e){$('#speakStatus').textContent=e.message}}
async function evaluateSpeakingTask(){if(!state.speakingSession)return;stopLive();$('#speakStatus').textContent='Gemini đang đánh giá bốn tiêu chí…';try{const result=await api('skills/speaking/evaluate','POST',{session_id:state.speakingSession.id}),scores=Object.entries(result.scores).map(([key,value])=>`${key}: ${value}/100`).join(' · ');$('#speakStatus').innerHTML=`<b>${esc(scores)}</b><br>${esc(result.feedback.feedback_vi)}<br>${(result.feedback.suggestions||[]).map(x=>'• '+esc(x)).join('<br>')}<br><small>${esc(result.feedback.pronunciation_note)} ${esc(result.disclaimer||'')}</small>`;await refreshPersonalization()}catch(e){$('#speakStatus').textContent=e.message}}
function listenTurn(){if(!state.user){openAuth();return}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){$('#speakStatus').textContent='Trình duyệt chưa hỗ trợ nhận dạng giọng nói. Hãy dùng Chrome/Edge hoặc nhập câu.';return}const rec=new Recognition();rec.lang='en-US';rec.interimResults=false;rec.onresult=e=>submitTurn(e.results[0][0].transcript);rec.onerror=e=>$('#speakStatus').textContent='Lỗi micro: '+e.error;rec.onstart=()=>$('#speakStatus').textContent='Đang nghe...';rec.start()}
function encodePCM(floatData,rate){const count=Math.floor(floatData.length*16000/rate),buf=new Int16Array(count);for(let i=0;i<count;i++){let v=Math.max(-1,Math.min(1,floatData[Math.floor(i*rate/16000)]));buf[i]=v<0?v*32768:v*32767}let binary='';const bytes=new Uint8Array(buf.buffer);for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary)}
async function startLive(){if(!state.runtime.gemini_live_enabled){$('#speakStatus').textContent='Gemini Live đang tắt trong môi trường thử nghiệm này.';return}if(!state.user){openAuth();return}if(liveSocket){stopLive();return}if(!window.confirm('Gemini Live sẽ sử dụng quota API và truyền âm thanh tới Gemini trong phiên này. Bắt đầu hội thoại trực tiếp?')){$('#speakStatus').textContent='Chưa kết nối Gemini Live.';return}try{
 micStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
 const proto=location.protocol==='https:'?'wss':'ws';liveSocket=new WebSocket(`${proto}://${location.host}/ws/speaking/live`);
 $('#speakStatus').textContent='Đang kết nối Gemini Live...';
 liveSocket.onopen=()=>liveSocket.send(JSON.stringify({csrf:decodeURIComponent(cookieValue('ss_csrf')),level:speakingLevel,topic:speakingTopic,session_id:state.speakingSession?.id||null}));
 liveSocket.onmessage=async event=>{const obj=JSON.parse(event.data);if(obj.error){$('#speakStatus').textContent=obj.error;stopLive();return}if(obj.status)return;
 if(obj.setupComplete){$('#speakStatus').textContent='Đang hội thoại trực tiếp — hãy nói tiếng Anh!';await startMicStreaming();return}
 const content=obj.serverContent||{};if(content.interrupted){if(audioContext){await audioContext.close();audioContext=null}playAt=0}
 if(content.inputTranscription?.text)logSpeaking(content.inputTranscription.text,true);
 if(content.outputTranscription?.text)logSpeaking(content.outputTranscription.text,false);
 for(const part of content.modelTurn?.parts||[]){if(part.inlineData?.data)playLiveAudio(part.inlineData.data,part.inlineData.mimeType||'')}
 };
 liveSocket.onclose=()=>{if($('#speakStatus'))$('#speakStatus').textContent='Đã ngắt kết nối Live';stopLive()};
 }catch(e){$('#speakStatus').textContent='Không thể mở micro: '+e.message;stopLive()}}
async function startMicStreaming(){if(!micStream||!liveSocket)return;micContext=new AudioContext();const source=micContext.createMediaStreamSource(micStream);micProcessor=micContext.createScriptProcessor(2048,1,1);micProcessor.onaudioprocess=e=>{if(liveSocket?.readyState===1){const data=encodePCM(e.inputBuffer.getChannelData(0),micContext.sampleRate);liveSocket.send(JSON.stringify({type:'audio',data}))}};source.connect(micProcessor);micProcessor.connect(micContext.destination)}
async function playLiveAudio(b64,mime){try{audioContext ||= new AudioContext({sampleRate:24000});const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));const pcm=new Int16Array(bytes.buffer);const rate=Number(mime.match(/rate=(\d+)/)?.[1]||24000);const buffer=audioContext.createBuffer(1,pcm.length,rate);const channel=buffer.getChannelData(0);for(let i=0;i<pcm.length;i++)channel[i]=pcm[i]/32768;const source=audioContext.createBufferSource();source.buffer=buffer;source.connect(audioContext.destination);playAt=Math.max(playAt,audioContext.currentTime+0.04);source.start(playAt);playAt+=buffer.duration}catch(e){console.warn('Audio playback:',e.message)}}
function stopLive(){const ws=liveSocket;liveSocket=null;if(ws&&ws.readyState<2)ws.close();if(micProcessor){micProcessor.disconnect();micProcessor=null}if(micContext){micContext.close().catch(()=>{});micContext=null}micStream?.getTracks().forEach(t=>t.stop());micStream=null;if(audioContext){audioContext.close().catch(()=>{});audioContext=null}playAt=0}
const oldNav=nav;nav=function(v){stopSpeech();if(state.view==='conversation'&&v!=='conversation')stopLive();oldNav(v)};
window.addEventListener('pagehide',()=>{stopSpeech();stopLive()});
window.addEventListener('beforeunload',()=>{stopSpeech();stopLive()});
